From 7732501346f47c6526146fb9996cf5050205eff7 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 17:18:30 +0100
Subject: [PATCH] applets/notifications: Keep popups clear of an auto-hiding
 panel

Popups are placed in the available screen area, which includes panels
that auto-hide, so revealing the panel holding the notification widget
left the popups covering it. Now popups also keep clear of that panel.

BUG: 512614
---
 applets/notifications/global/Globals.qml | 25 ++++++++++++++++++++++++
 1 file changed, 25 insertions(+)

diff --git a/applets/notifications/global/Globals.qml b/applets/notifications/global/Globals.qml
index 8e8e56f88d..99f78da513 100644
--- a/applets/notifications/global/Globals.qml
+++ b/applets/notifications/global/Globals.qml
@@ -139,6 +139,31 @@ QtObject {
                            containment.availableScreenRect.width,
                            containment.availableScreenRect.height);

+        // The available area includes auto-hiding panels. Still keep clear of the panel holding the widget:
+        // it shows up when the pointer reaches it, and the popups would then cover it.
+        const panelWindow = visualParent ? visualParent.Window.window : null;
+        if (panelWindow) {
+            let left = rect.left;
+            let top = rect.top;
+            let right = rect.right;
+            let bottom = rect.bottom;
+            switch (plasmoid.location) {
+            case PlasmaCore.Types.LeftEdge:
+                left = Math.max(left, panelWindow.x + panelWindow.width);
+                break;
+            case PlasmaCore.Types.RightEdge:
+                right = Math.min(right, panelWindow.x);
+                break;
+            case PlasmaCore.Types.TopEdge:
+                top = Math.max(top, panelWindow.y + panelWindow.height);
+                break;
+            case PlasmaCore.Types.BottomEdge:
+                bottom = Math.min(bottom, panelWindow.y);
+                break;
+            }
+            rect = Qt.rect(left, top, right - left, bottom - top);
+        }
+
         // When no explicit screen corner is configured,
         // restrict notification popup position by horizontal panel width
         if (visualParent && notificationSettings.popupPosition === NotificationManager.Settings.CloseToWidget
